# ---------------------------------------------------------------- core (bot_core.py)
import random as _random
import time as _time
try:
    from kit import Agent
except Exception:  # pragma: no cover
    class Agent(object):
        def new_table(self, rules, seat, n_players): pass
        def act(self, obs): raise NotImplementedError
        def hand_end(self, result): pass

_PC = _time.perf_counter
_R = _random.Random()
_rnd = _R.random
_sample = _R.sample

# ---------------- evaluator: rank-multiset dict + flush table
RK = [5 ** (c >> 2) for c in range(52)]
SK = [1 << (3 * (c & 3)) for c in range(52)]
RB = [1 << (c >> 2) for c in range(52)]
CM = [1 << c for c in range(52)]


def _straight_top(mask):
    for top in range(12, 3, -1):
        m = 0x1F << (top - 4)
        if mask & m == m:
            return top
    if mask & 0x100F == 0x100F:
        return 3
    return -1


ST = [_straight_top(m) for m in range(8192)]


def _pack(cat, ks):
    v = cat
    ks = list(ks)[:5]
    while len(ks) < 5:
        ks.append(0)
    for k in ks:
        v = (v << 4) | k
    return v


def _val_counts(cnt):
    desc = range(12, -1, -1)
    q = [r for r in desc if cnt[r] == 4]
    t = [r for r in desc if cnt[r] == 3]
    p = [r for r in desc if cnt[r] == 2]
    mask = 0
    for r in range(13):
        if cnt[r]:
            mask |= 1 << r
    st = ST[mask]
    present = [r for r in desc if cnt[r]]
    if q:
        return _pack(7, [q[0]] + [r for r in present if r != q[0]][:1])
    if t and (len(t) >= 2 or p):
        pp = max(t[1] if len(t) > 1 else -1, p[0] if p else -1)
        return _pack(6, [t[0], pp])
    if st >= 0:
        return _pack(4, [st])
    if t:
        return _pack(3, [t[0]] + [r for r in present if r != t[0]][:2])
    if len(p) >= 2:
        return _pack(2, [p[0], p[1]] + [r for r in present if r != p[0] and r != p[1]][:1])
    if p:
        return _pack(1, [p[0]] + [r for r in present if r != p[0]][:3])
    return _pack(0, present[:5])


VAL = {}


def _gen(r, left, cnt, key, n):
    if r == 13:
        if n >= 2:
            VAL[key] = _val_counts(cnt)
        return
    for c in range(0, min(4, left) + 1):
        cnt[r] = c
        _gen(r + 1, left - c, cnt, key + c * 5 ** r, n + c)
    cnt[r] = 0


_gen(0, 7, [0] * 13, 0, 0)

FL = [0] * 8192
for _m in range(8192):
    if bin(_m).count('1') >= 5:
        _st = ST[_m]
        FL[_m] = _pack(8, [_st]) if _st >= 0 else _pack(5, [r for r in range(12, -1, -1) if _m >> r & 1][:5])
FS = [-1] * 4096
for _k in range(4096):
    for _s in range(4):
        if (_k >> (3 * _s)) & 7 >= 5:
            FS[_k] = _s
# OUTS[mask]: number of ranks that would complete a straight not already present
OUTS = [0] * 8192
for _m in range(8192):
    if ST[_m] >= 0:
        continue
    _n = 0
    for _r in range(13):
        if not (_m >> _r & 1) and ST[_m | (1 << _r)] >= 0:
            _n += 1
    OUTS[_m] = _n


def ev7(cards):
    k = 0
    s = 0
    for c in cards:
        k += RK[c]
        s += SK[c]
    v = VAL[k]
    f = FS[s]
    if f >= 0:
        m = 0
        for c in cards:
            if c & 3 == f:
                m |= RB[c]
        fv = FL[m]
        if fv > v:
            v = fv
    return v


# ---------------- preflop tables
def hcls(c1, c2):
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2:
        r1, r2 = r2, r1
    if r1 == r2:
        return r1 * 13 + r1
    if (c1 & 3) == (c2 & 3):
        return r1 * 13 + r2
    return r2 * 13 + r1


def _combos_of(k):
    a, b = divmod(k, 13)
    out = []
    for s1 in range(4):
        for s2 in range(4):
            if a == b:
                if s1 < s2:
                    out.append((a * 4 + s1, a * 4 + s2))
            elif a > b:
                if s1 == s2:
                    out.append((a * 4 + s1, b * 4 + s2))
            else:
                if s1 != s2:
                    out.append((b * 4 + s1, a * 4 + s2))
    return out


PCT = [0.0] * 169
COMBOS = []      # (c1, c2, mask) sorted best -> worst
_cum = 0
for _k in PF_ORDER:
    _cs = _combos_of(_k)
    PCT[_k] = (_cum + len(_cs) * 0.5) / 1326.0
    for _a, _b in _cs:
        COMBOS.append((_a, _b, CM[_a] | CM[_b]))
    _cum += len(_cs)
NCOMB = len(COMBOS)


def req(k, p):
    """Heads-up equity of class k vs top-p range."""
    g = PF_PGRID
    if p <= g[0]:
        return PF_REQ[0][k]
    if p >= 1.0:
        return PF_REQ[-1][k]
    i = 1
    while g[i] < p:
        i += 1
    w = (p - g[i - 1]) / (g[i] - g[i - 1])
    return PF_REQ[i - 1][k] * (1 - w) + PF_REQ[i][k] * w


def combine(eqs):
    """Multiway equity from heads-up equities (independence approximation)."""
    if not eqs:
        return 1.0
    if len(eqs) == 1:
        return eqs[0]
    s = 0.0
    for e in eqs:
        e = min(max(e, 0.01), 0.99)
        s += (1 - e) / e
    return 1.0 / (1.0 + s)


# ---------------- ICM utility (Malmuth-Harville, others assumed equal)
PTS = [10.0, 7.0, 5.0, 4.0, 3.0, 2.0, 1.0, 0.0]


ICM_W = 1.0
BLUFF_DISC = True
FMULT = False
FTB2_SCALE = 0.8
PER_STREET = True


def icm(ch, total, n):
    if ICM_W >= 1.0:
        return _icm(ch, total, n)
    nn = min(max(n, 1), 8)
    lo = PTS[nn - 1]
    lin = lo + (sum(PTS[:nn]) - nn * lo) * max(0.0, min(1.0, ch / float(total or 1)))
    return ICM_W * _icm(ch, total, n) + (1 - ICM_W) * lin


def _icm(ch, total, n):
    if n < 1:
        n = 1
    if n > 8:
        n = 8
    if ch <= 0:
        return PTS[n - 1]
    if n == 1 or ch >= total:
        return 10.0
    o = (total - ch) / (n - 1.0)
    e = 0.0
    reach = 1.0
    k = n - 1
    p = 0
    while k > 0:
        d = ch + k * o
        e += reach * ch / d * PTS[p]
        reach *= k * o / d
        k -= 1
        p += 1
    return e + reach * PTS[p]


# ---------------- opponent model
class Opp(object):
    __slots__ = ('hands', 'vpip', 'pfr', 'oo', 'on', 'tbo', 'tbn', 'f1f', 'sto', 'stf', 'ao', 'ac',
                 'bo', 'bn', 'fo', 'ff', 'fc', 'fr', 'sh', 'rfo', 'rff', 'f3o', 'f3f', 'sdb', 'sdv', 'sdc', 'sdw', 'fo2', 'ff2')

    def __init__(self):
        for a in self.__slots__:
            setattr(self, a, 0)

    # estimates with priors (prior mean, prior weight)
    def vpip_e(self):
        return (self.vpip + 0.30 * 6) / (self.hands + 6)

    def pfr_e(self):
        return (self.pfr + 0.16 * 6) / (self.hands + 6)

    def open_e(self):
        return (self.on + 0.20 * 5) / (self.oo + 5)

    def tb_e(self):
        return (self.tbn + 0.07 * 6) / (self.tbo + 6)

    def fts_e(self):
        return (self.stf + 0.55 * 4) / (self.sto + 4)

    def callai_e(self, prior):
        return (self.ac + prior * 4) / (self.ao + 4)

    def ftb_e(self):
        return (self.ff + 0.45 * 6) / (self.fo + 6)

    def ftb2_e(self):
        """Fold to a bet on the turn/river: shrinks to his overall rate scaled down."""
        return (self.ff2 + self.ftb_e() * FTB2_SCALE * 5) / (self.fo2 + 5)

    def agg_e(self):
        return (self.bn + 0.35 * 6) / (self.bo + 6)

    def f2r_e(self):
        p0 = 0.40 * self.ftb_e() / 0.45
        p0 = 0.05 if p0 < 0.05 else (0.4 if p0 > 0.4 else p0)
        return (self.rff + p0 * 4) / (self.rfo + 4)

    def f3_e(self):
        return (self.f3f + 0.50 * 4) / (self.f3o + 4)

    def bluff_e(self):
        """P(bet | air) estimate: aggression rate, scaled by the bluff share seen at showdown."""
        b = (self.agg_e() - 0.2) * 1.5
        r = (self.sdb + 0.25 * 4) / (self.sdb + self.sdv + 4.0)
        b *= 0.5 + 2.0 * r
        return min(0.9, max(0.04, b))

    def float_e(self):
        """P(call a bet | air) estimate."""
        f = (0.65 - self.ftb_e()) * 1.3
        r = (self.sdw + 0.12 * 4) / (self.sdc + self.sdw + 4.0)
        f *= 0.6 + 3.3 * r
        return min(0.85, max(0.04, f))


KINDS = ('fold', 'check', 'call', 'raise')
_ERRS = [0]


class Bot(Agent):
    DEBUG = None
    def __init__(self):
        self.new_table({}, 0, 8)

    def new_table(self, rules, seat, n_players):
        try:
            n = int(n_players) if n_players else 8
        except Exception:
            n = 8
        self.n = max(2, min(10, n))
        self.me = seat
        self.opp = [Opp() for _ in range(max(self.n, 10))]
        self.hno = None
        self.ok = False
        self.done = True

    # ------------------------------------------------------------ hand tracking
    def _begin(self, obs):
        n = len(obs.stacks)
        if n > len(self.opp):
            self.opp.extend(Opp() for _ in range(n - len(self.opp)))
        self.hno = obs.hand_no
        self.done = False
        self.hidx = 0
        self.N = n
        self.me = obs.seat
        self.ok = False
        self.pfa = [[] for _ in range(n)]     # preflop action labels
        self.post = [[] for _ in range(n)]    # postflop action codes 0 chk 1 call 2 bet 3 raise
        self.hv = [0] * n
        self.hp = [0] * n
        self.seen = [False] * n
        self.last_board = ()
        if obs.street != 0:
            return
        bb_amt = obs.blinds[1] if obs.blinds else 0
        sb_amt = obs.blinds[0] if obs.blinds else 0
        start = [obs.stacks[i] + obs.bets[i] for i in range(n)]
        alive = [i for i in range(n) if start[i] > 0]
        if len(alive) < 2:
            return
        b = obs.button

        def nxt(s):
            for d in range(1, n + 1):
                j = (s + d) % n
                if start[j] > 0:
                    return j
            return s
        if len(alive) == 2:
            sb = b if start[b] > 0 else nxt(b)
        else:
            sb = nxt(b)
        bbs = nxt(sb)
        hist = obs.history or []
        real = [h for h in hist if isinstance(h, (tuple, list)) and len(h) == 2 and isinstance(h[1], (tuple, list))
                and len(h[1]) >= 1 and h[1][0] in KINDS]
        if not real:
            # derive blinds from bets if possible
            bets = obs.bets
            s1 = [i for i in range(n) if bets[i] == sb_amt and bets[i] > 0]
            s2 = [i for i in range(n) if bets[i] == bb_amt and bets[i] > 0]
            if len(s2) == 1 and len(s1) == 1 and s1[0] != s2[0]:
                sb, bbs = s1[0], s2[0]
        self.sb, self.bbs = sb, bbs
        self.start = start
        c = [0] * n
        c[sb] = min(sb_amt, start[sb])
        c[bbs] = min(bb_amt, start[bbs])
        self.contrib = c
        self.rem = [start[i] - c[i] for i in range(n)]
        self.active = [start[i] > 0 for i in range(n)]
        self.maxbet = max(c)
        self.bb = bb_amt or 1
        self.street = 0
        self.potp = 0
        self.aggr_prev = -1
        self.pf_nr = 0
        self.pf_raiser = -1
        self.pf_callers = 0
        self.limpers = 0
        self.aggr = -1
        self.to_act = set(i for i in alive if self.rem[i] > 0)
        self.allin_bet = False
        self.skip_posts = True
        self.ok = True

    def _sync(self, hist):
        if not self.ok or not hist:
            return
        i = self.hidx
        L = len(hist)
        while i < L:
            h = hist[i]
            i += 1
            try:
                seat = h[0]
                a = h[1]
                kind = a[0]
                amt = a[1] if len(a) > 1 else 0
            except Exception:
                continue
            if kind not in KINDS:
                continue
            if self.skip_posts:
                # blind posts may appear as the first two entries
                if seat == self.sb and self.street == 0 and kind in ('call', 'raise') and amt == self.contrib[self.sb] \
                        and i < L and hist[i][0] == self.bbs:
                    try:
                        a2 = hist[i][1]
                        if a2[0] in ('call', 'raise') and a2[1] == self.contrib[self.bbs]:
                            i += 1
                            self.skip_posts = False
                            continue
                    except Exception:
                        pass
                self.skip_posts = False
            try:
                self._proc(seat, kind, int(amt or 0))
            except Exception:
                self.ok = False
                break
        self.hidx = i

    def _proc(self, seat, kind, amt):
        if seat < 0 or seat >= self.N or not self.active[seat]:
            return
        c = self.contrib
        facing = self.maxbet > c[seat]
        st = self.street
        o = self.opp[seat] if seat != self.me else None
        if st == 0:
            if kind == 'raise':
                lab = 'open' if self.pf_nr == 0 else ('3b' if self.pf_nr == 1 else '4b')
                tot = c[seat] + self.rem[seat]
                if amt >= tot:
                    lab += 'A'
                self.pfa[seat].append((lab, len(self.to_act) - (1 if seat in self.to_act else 0)))
            elif kind == 'call':
                self.pfa[seat].append(('limp' if self.pf_nr == 0 else 'call', 0))
            if o is not None:
                self.seen[seat] = True
                if kind in ('call', 'raise'):
                    self.hv[seat] = 1
                if kind == 'raise':
                    self.hp[seat] = 1
                if self.pf_nr == 0:
                    o.oo += 1
                    if kind == 'raise':
                        o.on += 1
                elif self.pf_nr == 1 and seat != self.pf_raiser:
                    o.tbo += 1
                    if kind == 'raise':
                        o.tbn += 1
                    elif kind == 'fold':
                        o.f1f += 1
                    if (seat == self.sb or seat == self.bbs) and self.pf_callers == 0:
                        o.sto += 1
                        if kind == 'fold':
                            o.stf += 1
                if seat == self.pf_raiser and self.pf_nr >= 2 and facing:
                    o.f3o += 1
                    if kind == 'fold':
                        o.f3f += 1
                if facing and self.allin_bet:
                    o.ao += 1
                    if kind == 'call':
                        o.ac += 1
                if kind == 'raise' and amt >= c[seat] + self.rem[seat]:
                    o.sh += 1
        else:
            code = 0 if kind == 'check' else (1 if kind == 'call' else (2 if kind == 'raise' and not facing else (3 if kind == 'raise' else -1)))
            if code >= 0:
                frac = 0.0
                if code >= 2:
                    pb = self.potp + sum(c) + (self.maxbet - c[seat])
                    frac = (amt - self.maxbet) / float(max(1, pb))
                self.post[seat].append((st, code, frac))
            if o is not None:
                if not facing:
                    o.bo += 1
                    if kind == 'raise':
                        o.bn += 1
                else:
                    o.fo += 1
                    if kind == 'fold':
                        o.ff += 1
                    if st >= 2:
                        o.fo2 += 1
                        if kind == 'fold':
                            o.ff2 += 1
                    elif kind == 'call':
                        o.fc += 1
                    elif kind == 'raise':
                        o.fr += 1
                    if self.aggr_prev == seat:
                        o.rfo += 1
                        if kind == 'fold':
                            o.rff += 1
                if facing and self.allin_bet:
                    o.ao += 1
                    if kind == 'call':
                        o.ac += 1
        # apply
        ta = self.to_act
        if kind == 'fold':
            self.active[seat] = False
            ta.discard(seat)
        elif kind == 'check':
            ta.discard(seat)
        elif kind == 'call':
            put = min(max(self.maxbet - c[seat], 0), self.rem[seat])
            c[seat] += put
            self.rem[seat] -= put
            ta.discard(seat)
            if st == 0:
                if self.pf_nr >= 1:
                    self.pf_callers += 1
                else:
                    self.limpers += 1
        else:  # raise
            put = min(max(amt - c[seat], 0), self.rem[seat])
            c[seat] += put
            self.rem[seat] -= put
            if c[seat] > self.maxbet:
                self.maxbet = c[seat]
                self.to_act = ta = set(j for j in range(self.N) if self.active[j] and self.rem[j] > 0 and j != seat)
                if st == 0:
                    self.pf_nr += 1
                    self.pf_raiser = seat
                    self.pf_callers = 0
                self.aggr_prev = self.aggr
                self.aggr = seat
                self.allin_bet = self.rem[seat] == 0
            else:
                ta.discard(seat)
        nact = 0
        for j in range(self.N):
            if self.active[j]:
                nact += 1
        if nact <= 1:
            self.to_act = set()
            return
        if not ta:
            # street over
            self.street += 1
            self.potp += sum(self.contrib)
            self.contrib = [0] * self.N
            self.maxbet = 0
            self.aggr_prev = -1
            self.aggr = -1
            self.allin_bet = False
            self.to_act = set(j for j in range(self.N) if self.active[j] and self.rem[j] > 0)
            if len(self.to_act) <= 1:
                self.to_act = set()

    def _finish(self, result=None):
        if self.done:
            return
        self.done = True
        try:
            if result is not None and self.ok:
                h = None
                if isinstance(result, dict):
                    h = result.get('history')
                if h:
                    self._sync(h)
            for j in range(self.N):
                if self.seen[j] and j != self.me:
                    o = self.opp[j]
                    o.hands += 1
                    o.vpip += self.hv[j]
                    o.pfr += self.hp[j]
            if isinstance(result, dict):
                self._showdown(result)
        except Exception:
            pass

    def _showdown(self, result):
        sd = result.get('showdown') or result.get('shown') or result.get('hands')
        board = result.get('board') or self.last_board
        if not sd or not board or len(board) < 5:
            return
        items = sd.items() if isinstance(sd, dict) else sd
        for it in items:
            try:
                seat, hole = it
                seat = int(seat)
                if seat == self.me or seat < 0 or seat >= self.N:
                    continue
                hole = tuple(hole)
                if len(hole) != 2:
                    continue
            except Exception:
                continue
            t, dr = self._tier(hole[0], hole[1], tuple(board))
            acts = [x[1] for x in self.post[seat]] if self.ok else []
            o = self.opp[seat]
            if 2 in acts or 3 in acts:
                if t <= 1:
                    o.sdb += 1
                else:
                    o.sdv += 1
            elif 1 in acts:
                if t == 0:
                    o.sdw += 1
                else:
                    o.sdc += 1

    def hand_end(self, result):
        try:
            self._finish(result)
        except Exception:
            pass

    # ------------------------------------------------------------ helpers
    def _tier(self, a, b, board):
        bk = 0
        bs = 0
        bm = 0
        bmax = 0
        for c in board:
            bk += RK[c]
            bs += SK[c]
            bm |= RB[c]
            if c >> 2 > bmax:
                bmax = c >> 2
        bv = VAL.get(bk, 0) if len(board) >= 2 else 0
        return self._tier_fast(a, b, bk, bs, bm, bmax, bv >> 20, len(board))

    @staticmethod
    def _tier_fast(a, b, bk, bs, bm, bmax, bcat, nb):
        s = bs + SK[a] + SK[b]
        f = FS[s]
        draw = False
        if f >= 0:
            if (a & 3) == f or (b & 3) == f:
                return 3, False
        elif nb < 5:
            sa = (s >> (3 * (a & 3))) & 7
            sbb = (s >> (3 * (b & 3))) & 7
            if sa == 4 or sbb == 4:
                draw = True
        v = VAL[bk + RK[a] + RK[b]]
        cat = v >> 20
        if nb < 5 and not draw:
            m = bm | RB[a] | RB[b]
            if OUTS[m] - OUTS[bm] >= 2 and cat < 4:
                draw = True
        if cat <= bcat:
            return 0, draw
        if cat >= 3:
            return 3, draw
        if cat == 2:
            if bcat == 0:
                return 3, draw
            return 2, draw
        # one pair made with hole card(s)
        pr = (v >> 16) & 15
        if pr >= bmax:
            return 2, draw
        return 1, draw

    def _range_p(self, j):
        o = self.opp[j]
        p = 1.0
        for lab, nb in self.pfa[j]:
            allin = lab.endswith('A')
            base = lab[:-1] if allin else lab
            if base == 'open':
                q = o.open_e()
                if nb >= 5:
                    q *= 0.7
                elif nb <= 1:
                    # blind vs blind / heads-up opens are wide; trust his own rate once seen enough
                    q = max(q * 1.5, 0.45 * 5.0 / (o.oo + 5.0))
                elif nb <= 2:
                    q *= 1.5
                if allin:
                    q = max(q, (o.sh + 0.06 * 3) / (o.hands + 3) * 1.2)
            elif base == '3b':
                q = o.tb_e()
                if allin:
                    q = max(q, (o.sh + 0.04 * 3) / (o.hands + 3))
            elif base == '4b':
                q = max(0.02, o.tb_e() * 0.4)
                if allin:
                    q = max(q, (o.sh + 0.03 * 3) / (o.hands + 3))
            elif base == 'limp':
                q = o.vpip_e()
            else:  # call
                q = o.vpip_e() * 0.9
            if q < p:
                p = q
        return min(1.0, max(0.015, p))

    def _alive(self, obs):
        n = 0
        for i in range(len(obs.stacks)):
            if obs.stacks[i] > 0 or obs.in_hand[i]:
                n += 1
        return max(n, 1)

    @staticmethod
    def _safe(obs):
        lg = obs.legal
        if 'check' in lg:
            return ('check', 0)
        return ('fold', 0)

    def _raise_to(self, obs, x):
        lg = obs.legal
        if 'raise' not in lg:
            if 'call' in lg:
                return ('call', 0)
            return ('check', 0) if 'check' in lg else ('fold', 0)
        mn, mx = obs.min_raise, obs.max_raise
        x = int(x)
        if x < mn:
            x = mn
        if x > mx:
            x = mx
        if x > 0.82 * mx:
            x = mx
        return ('raise', int(x))

    # ------------------------------------------------------------ act
    def act(self, obs):
        t0 = _PC()
        try:
            if obs.hand_no != self.hno or self.done:
                if not self.done:
                    self._finish(None)
                # a new table without new_table(): hand numbers restart -> forget the old opponents
                try:
                    if self.hno is not None and obs.hand_no is not None and obs.hand_no < self.hno:
                        self.opp = [Opp() for _ in range(max(len(obs.stacks), 10))]
                except Exception:
                    pass
                self._begin(obs)
            if self.ok:
                self._sync(obs.history)
                if self.street != obs.street:
                    self.ok = False
                else:
                    # resync chip state from the observation (absorbs engine rule differences)
                    n = self.N
                    if len(obs.bets) == n:
                        self.contrib = list(obs.bets)
                        self.rem = list(obs.stacks)
                        self.potp = obs.pot
                        mb = max(obs.bets)
                        if mb > self.maxbet or obs.street > 0:
                            self.maxbet = mb
            self.last_board = tuple(obs.board or ())
            if obs.street == 0:
                a = self._preflop(obs)
            else:
                a = self._postflop(obs, t0)
            return self._check_legal(a, obs)
        except Exception:
            _ERRS[0] += 1
            try:
                return self._safe(obs)
            except Exception:
                return ('fold', 0)

    def _check_legal(self, a, obs):
        lg = obs.legal
        k = a[0]
        if k == 'raise':
            if 'raise' not in lg:
                return ('call', 0) if 'call' in lg else self._safe(obs)
            x = int(a[1])
            if x < obs.min_raise or x > obs.max_raise:
                x = min(max(x, obs.min_raise), obs.max_raise)
            return ('raise', x)
        if k == 'fold' and 'check' in lg:
            return ('check', 0)
        if k in lg:
            return (k, 0)
        if k == 'call' and 'check' in lg:
            return ('check', 0)
        if k == 'check' and 'call' in lg:
            return ('fold', 0)
        return self._safe(obs)

    # ------------------------------------------------------------ preflop
    def _preflop(self, obs):
        me = obs.seat
        n = len(obs.stacks)
        try:
            sb_amt, bb = obs.blinds
            sb_amt = int(sb_amt or 0)
            bb = int(bb or 0)
        except Exception:
            sb_amt, bb = 0, 0
        if bb <= 0:
            bb = max(max(obs.bets), 2)
            sb_amt = bb // 2
        bb = bb or 1
        h = obs.hole
        k = hcls(h[0], h[1])
        q = PCT[k]
        st = obs.stacks[me]
        mybet = obs.bets[me]
        to_call = obs.to_call
        T = obs.pot + sum(obs.bets)
        total = sum(obs.stacks) + T
        nal = self._alive(obs)
        opps = [i for i in range(n) if i != me and obs.in_hand[i]]
        if not opps:
            return ('check', 0) if 'check' in obs.legal else ('call', 0)
        mytot = st + mybet
        eff = min(mytot, max(obs.stacks[i] + obs.bets[i] for i in opps))
        effbb = eff / float(bb)
        maxbet = max(obs.bets)
        ok = self.ok
        if ok:
            nr = self.pf_nr
            raiser = self.pf_raiser
            behind = [j for j in self.to_act if j != me]
            limpers = self.limpers
        else:
            nr = 0 if maxbet <= bb else (1 if maxbet <= 5 * bb else 2)
            raiser = max(range(n), key=lambda i: obs.bets[i]) if nr else -1
            behind = [j for j in opps if obs.bets[j] < maxbet and obs.stacks[j] > 0]
            limpers = 0
        U0 = icm(st, total, nal)

        if nr == 0:
            # ---------------- unopened
            nb = len(behind)
            if effbb <= 13.5 or (effbb <= 18 and nb <= 2):
                ev = self._shove_ev(obs, k, behind + [j for j in opps if j not in behind and obs.stacks[j] > 0],
                                    st, T, total, nal, effbb)
                if ev > U0 + 0.0005:
                    return ('raise', obs.max_raise)
                return self._safe(obs)
            if nal == 2:
                th = 0.70 if nb >= 1 else 0.0
            else:
                th = {0: 0.0, 1: 0.50, 2: 0.42, 3: 0.29, 4: 0.22, 5: 0.17, 6: 0.14}.get(nb, 0.12)
            if 1 <= nb <= 3:
                fts = [self.opp[j].fts_e() for j in behind]
                if fts:
                    th *= 1.0 + 1.3 * (sum(fts) / len(fts) - 0.55)
            vp = [self.opp[j].vpip_e() for j in behind]
            loose = sum(vp) / len(vp) if vp else 0.3
            tb = max([self.opp[j].tb_e() for j in behind] or [0.07])
            if tb > 0.14:
                th *= 0.85
            size = 2.3 if nb >= 3 else 2.5
            if loose > 0.5:
                size += 0.5
            if limpers:
                th *= 0.6
                size = 3.0 + limpers
            if to_call == 0:  # BB option in limped pot
                if q <= 0.10 or (q <= 0.25 and limpers <= 1 and _rnd() < 0.3):
                    return self._raise_to(obs, (3.5 + limpers) * bb)
                return ('check', 0)
            if q <= th:
                return self._raise_to(obs, size * bb)
            # complete / limp behind with speculative hands in cheap multiway pots
            if limpers >= 1 and to_call <= bb and effbb > 30 and q <= 0.45:
                return ('call', 0)
            if nal > 2 and nb == 1 and me == (self.sb if ok else -1) and to_call <= sb_amt and q <= 0.55 \
                    and self.opp[behind[0]].pfr_e() < 0.18:
                return ('call', 0)
            return self._safe(obs)

        # ---------------- facing a raise
        rp = self._range_p(raiser) if (ok and raiser >= 0) else 0.15
        eqs = [req(k, rp)]
        if ok:
            for j in opps:
                if j != raiser and self.pfa[j]:
                    eqs.append(req(k, self._range_p(j)))
        # players behind may still wake up
        e = combine(eqs)
        wake = 1.0
        for j in behind:
            if j != raiser:
                wake *= 0.97
        r_tot = obs.stacks[raiser] + obs.bets[raiser] if raiser >= 0 else maxbet
        raiser_allin = raiser >= 0 and obs.stacks[raiser] == 0
        commit = to_call >= 0.4 * st or effbb <= 22 or maxbet >= 0.3 * mytot
        if raiser_allin or to_call >= st:
            # pure call / fold all-in decision
            return self._call_allin_pf(obs, e * wake, st, T, to_call, total, nal, opps)
        if commit:
            # shove or fold (or call when the price is tiny)
            F = 0.0
            if raiser >= 0:
                o = self.opp[raiser]
                F = o.f3_e() if nr == 1 else o.f3_e() * 0.6
                if obs.bets[raiser] >= 0.4 * r_tot:
                    F *= 0.35
                for j in opps:
                    if j != raiser and obs.bets[j] > 0:
                        F *= 0.75
            cont = max(0.015, rp * (1 - F))
            ec = req(k, cont) * wake
            if raiser >= 0:
                add_their = max(0, min(st + mybet, r_tot) - obs.bets[raiser])
                risk = min(st, max(0, r_tot - mybet))
                nwin = nal - 1 if r_tot <= st + mybet else nal
            else:
                risk = min(st, max(obs.stacks[j] + obs.bets[j] - mybet for j in opps))
                add_their = risk
                nwin = nal
            win_ch = st + T + add_their
            Us = F * icm(st + T, total, nal) + (1 - F) * (ec * icm(win_ch, total, nwin) + (1 - ec) * icm(st - risk, total, nal))
            best, act = U0, self._safe(obs)
            if Us > best:
                best, act = Us, ('raise', obs.max_raise)
            # flat call when cheap relative to pot
            if to_call < 0.25 * st:
                R = 0.8
                Uc = e * wake * R * icm(self._win_stack(obs, to_call), total, nal) + (1 - e * wake * R) * icm(st - to_call, total, nal)
                if Uc > best:
                    best, act = Uc, ('call', 0)
            return act
        # deep: value 3bet / call / fold
        ip = self._ip_pre(obs, raiser)
        vth = max(0.03, (0.38 if nr == 1 else 0.3) * rp)
        if nr >= 2:
            vth = max(0.012, 0.4 * rp)
        if q <= vth:
            mult = 3.0 if ip else 3.6
            if nr >= 2:
                mult = 2.4
            x = maxbet * mult + self.pf_callers * maxbet if ok else maxbet * mult
            if x >= 0.38 * mytot:
                x = obs.max_raise
            return self._raise_to(obs, x)
        # occasional light 3bet vs foldy openers in position
        if nr == 1 and ip and raiser >= 0 and self.opp[raiser].f3_e() > 0.62 and 0.05 < q < 0.30 and \
                (h[0] & 3) == (h[1] & 3) and _rnd() < 0.35 and len(opps) == 1:
            return self._raise_to(obs, maxbet * 3.0)
        po = to_call / float(T + to_call)
        R = 0.88 if ip else (0.72 if (self.ok and me == self.bbs) else 0.64)
        if self.ok and me == self.bbs:
            R += 0.05
        if len(opps) >= 2:
            R -= 0.05
        if nr >= 2:
            R -= 0.05
        ecall = e * wake * R
        # set mining with pairs and deep stacks
        if h[0] >> 2 == h[1] >> 2 and eff >= 15 * to_call:
            ecall = max(ecall, po + 0.02)
        if ecall >= po:
            return ('call', 0)
        return self._safe(obs)

    @staticmethod
    def _win_stack(obs, call):
        """Our stack if we put in `call` more now and win: chips an opponent bet beyond our total come back to him."""
        me = obs.seat
        mine = obs.bets[me] + call
        w = obs.stacks[me] - call + obs.pot + mine
        bets = obs.bets
        for i in range(len(bets)):
            if i != me:
                b = bets[i]
                w += b if b < mine else mine
        return w

    def _ip_pre(self, obs, raiser):
        n = len(obs.stacks)
        me = obs.seat
        b = obs.button
        pm = (me - b - 1) % n
        if raiser < 0:
            return True
        pr = (raiser - b - 1) % n
        return pm > pr

    def _shove_ev(self, obs, k, callers, st, T, total, nal, effbb):
        """ICM utility of open-shoving now."""
        pnone = 1.0
        ev = 0.0
        me = obs.seat
        prior = min(0.4, 0.12 + 1.0 / max(effbb, 1.0))
        reach = 1.0
        for j in callers:
            if not obs.in_hand[j] or j == me:
                continue
            o = self.opp[j]
            pc = o.callai_e(prior)
            pc = min(0.9, max(0.02, pc))
            jt = obs.stacks[j] + obs.bets[j]
            risk = min(st + obs.bets[me], jt) - obs.bets[me]
            if risk <= 0:
                continue
            e = req(k, pc)
            p = reach * pc
            nwin = nal - 1 if jt <= st + obs.bets[me] else nal
            ev += p * (e * icm(st + T + risk + obs.bets[me] - obs.bets[j], total, nwin) +
                       (1 - e) * icm(st - risk, total, nal))
            reach *= (1 - pc)
        ev += reach * icm(st + T, total, nal)
        return ev

    def _call_allin_pf(self, obs, e, st, T, to_call, total, nal, opps):
        U0 = icm(st, total, nal)
        call = min(to_call, st)
        # if we call and win we collect T + matched call (excess returns)
        win = self._win_stack(obs, call)
        # opponent bust bonus
        bust = 0
        mytot = st + obs.bets[obs.seat]
        for j in opps:
            if obs.stacks[j] == 0 and obs.bets[j] <= mytot:
                bust += 1
        nwin = max(1, nal - (1 if bust and len(opps) == 1 else 0))
        Uc = e * icm(win, total, nwin) + (1 - e) * icm(st - call, total, nal)
        if Uc > U0:
            return ('call', 0)
        return self._safe(obs)

    # ------------------------------------------------------------ postflop
    def _postflop(self, obs, t0):
        me = obs.seat
        n = len(obs.stacks)
        board = tuple(obs.board)
        nb = len(board)
        h = obs.hole
        st = obs.stacks[me]
        mybet = obs.bets[me]
        C = obs.to_call
        T = obs.pot + sum(obs.bets)
        total = sum(obs.stacks) + T
        nal = self._alive(obs)
        opps = [i for i in range(n) if i != me and obs.in_hand[i]]
        if not opps:
            return ('check', 0) if 'check' in obs.legal else ('call', 0)
        ok = self.ok
        # opponent descriptors
        bk = 0
        bs = 0
        bm = 0
        bmax = 0
        known = CM[h[0]] | CM[h[1]]
        for c in board:
            bk += RK[c]
            bs += SK[c]
            bm |= RB[c]
            known |= CM[c]
            if c >> 2 > bmax:
                bmax = c >> 2
        bcat = VAL[bk] >> 20
        descs = []
        for j in opps:
            o = self.opp[j]
            p = self._range_p(j) if ok else 0.6
            npc = max(8, int(p * NCOMB))
            acts = self.post[j] if ok else []
            b = o.bluff_e()
            fa = o.float_e()
            r = (o.sdb + 1.0) / (o.sdb + o.sdv + 4.0)
            ds = (0.42 - r) / 0.2
            ds = 0.0 if ds < 0 else (1.0 if ds > 1 else ds)
            descs.append((j, npc, acts, b, fa, ds))
        res = self._mc(h, board, known, bk, bs, bm, bmax, bcat, descs, t0)
        e, ec, er, cps, crs, nsamp = res
        if nsamp < 16:
            # too few samples (time pressure): shrink toward a made-hand prior
            t, dr = self._tier_fast(h[0], h[1], bk, bs, bm, bmax, bcat, nb)
            pe = (0.22, 0.42, 0.6, 0.82)[t] + (0.1 if dr else 0.0)
            pe /= (1.0 + 0.35 * (len(opps) - 1))
            wgt = 16.0 - nsamp
            e = (e * nsamp + pe * wgt) / 16.0
            ec = (ec * nsamp + pe * 0.85 * wgt) / 16.0
            er = (er * nsamp + pe * 0.75 * wgt) / 16.0
        nst = 4 - nb  # streets left incl current: flop 1? -> flop=3 cards -> 1
        river = nb == 5
        ip = self._ip_post(obs, opps)
        Rr = 1.0 if river else (0.95 if ip else 0.86)
        Rc = 1.0 if river else (0.92 if ip else 0.85)
        U0 = icm(st, total, nal)
        best_u = None
        best = None
        cand = []
        if C == 0:
            # check
            Uchk = e * Rr * icm(st + T, total, nal) + (1 - e * Rr) * U0
            cand.append((Uchk, ('check', 0)))
            if 'raise' in obs.legal:
                sizes = (0.33, 0.6, 0.9, 1.5, 2.3) if max(d[4] for d in descs) > 0.45 else (0.33, 0.6, 0.9, 1.5)
                for f in sizes:
                    B = int(T * f)
                    if B < obs.min_raise:
                        B = obs.min_raise
                    if B > st:
                        B = st
                    if B <= 0:
                        continue
                    if B >= 0.82 * st:
                        B = st
                    Fall = 1.0
                    for idx, d in enumerate(descs):
                        o = self.opp[d[0]]
                        if FMULT:
                            tm = (o.ftb_e() / 0.45) ** 0.6
                            tm = 0.3 if tm < 0.3 else (1.7 if tm > 1.7 else tm)
                            fj = (1 - cps[idx]) * tm
                        else:
                            fj = 0.5 * (o.ftb_e() if nb == 3 else o.ftb2_e()) + 0.5 * (1 - cps[idx])
                        fj *= (B / (T * 0.6)) ** 0.3
                        fj = min(0.95, max(0.02, fj))
                        Fall *= fj
                    ecb = ec - 0.05 * (B / float(T) - 0.6)
                    ecb = min(0.99, max(0.0, ecb)) * Rc
                    Bc = min(B, max(obs.stacks[j] for j in opps))
                    U = Fall * icm(st + T, total, nal) + (1 - Fall) * (ecb * icm(st + T + Bc, total, nal) +
                                                                       (1 - ecb) * icm(st - Bc, total, nal))
                    cand.append((U, ('raise', mybet + B)))
                    if B >= st:
                        break
        else:
            call = min(C, st)
            cand.append((U0, ('fold', 0)))
            Rcall = 1.0 if (river or call >= st) else Rr
            ecall = e * Rcall
            Uc = ecall * icm(self._win_stack(obs, call), total, nal) + (1 - ecall) * icm(st - call, total, nal)
            cand.append((Uc, ('call', 0)))
            if 'raise' in obs.legal and call < st:
                maxb = max(obs.bets)
                for mult in (2.8, 0):
                    if mult:
                        X = int(maxb * mult + (T - sum(obs.bets)) * 0.3)
                        if X < obs.min_raise:
                            X = obs.min_raise
                    else:
                        X = obs.max_raise
                    if X > obs.max_raise:
                        X = obs.max_raise
                    if X >= 0.8 * obs.max_raise:
                        X = obs.max_raise
                    A = X - mybet
                    if A <= call:
                        continue
                    aggr = self.aggr if ok else -1
                    Fr = 1.0
                    for idx, d in enumerate(descs):
                        o = self.opp[d[0]]
                        if d[0] == aggr or aggr < 0:
                            if FMULT:
                                tm = (o.f2r_e() / 0.40) ** 0.6
                                tm = 0.3 if tm < 0.3 else (1.7 if tm > 1.7 else tm)
                                fj = (1 - crs[idx]) * tm
                            else:
                                fj = 0.5 * o.f2r_e() + 0.5 * (1 - crs[idx])
                        else:
                            if FMULT:
                                tm = (o.ftb_e() / 0.45) ** 0.6
                                tm = 0.3 if tm < 0.3 else (1.7 if tm > 1.7 else tm)
                                fj = (1 - crs[idx]) * tm
                            else:
                                fj = 0.5 * (o.ftb_e() if nb == 3 else o.ftb2_e()) + 0.5 * (1 - crs[idx])
                        # price: nobody folds when getting a huge price
                        their_req = (X - maxb) / float(T + A + (X - maxb))
                        pfac = their_req / 0.30
                        if pfac < 1.0:
                            fj *= pfac ** 1.5
                        if obs.stacks[d[0]] == 0:
                            fj = 0.0
                        fj = min(0.95, max(0.0, fj))
                        Fr *= fj
                    erx = er * (1.0 if (river or X >= obs.max_raise) else Rc)
                    their_add = min(X - maxb, max(obs.stacks[j] for j in opps))
                    U = Fr * icm(st + T, total, nal) + (1 - Fr) * (erx * icm(st + T + their_add, total, nal) +
                                                                  (1 - erx) * icm(st - min(A, call + their_add), total, nal))
                    cand.append((U, ('raise', X)))
                    if X >= obs.max_raise:
                        break
        for U, a in cand:
            if best_u is None or U > best_u + 1e-9:
                best_u, best = U, a
        if self.DEBUG:
            self.DEBUG.append((obs.hand_no, obs.street, obs.hole, board, round(e, 3), round(ec, 3), round(er, 3), nsamp,
                               [round(x, 2) for x in cps], T, C, st, [(round(U - U0, 4), a) for U, a in cand], best))
        if best[0] == 'raise':
            return self._raise_to(obs, best[1])
        return best

    def _ip_post(self, obs, opps):
        n = len(obs.stacks)
        b = obs.button
        pm = (obs.seat - b - 1) % n
        for j in opps:
            if obs.stacks[j] > 0 and (j - b - 1) % n > pm:
                return False
        return True

    def _mc(self, h, board, known, bk, bs, bm, bmax, bcat, descs, t0):
        nb = len(board)
        need = 5 - nb
        deck = [c for c in range(52) if not (known >> c) & 1]
        nd = len(deck)
        nopp = len(descs)
        tf = self._tier_fast
        h0, h1 = h
        mk0 = bk + RK[h0] + RK[h1]
        ms0 = bs + SK[h0] + SK[h1]
        bcards = board
        W = Ww = 0.0
        Wc = Wcw = 0.0
        Wr = Wrw = 0.0
        cps = [0.0] * nopp
        crs = [0.0] * nopp
        # per-opponent tables by bucket: air, draw, weak pair, top pair/overpair, strong
        tabs = []
        cur_st = nb - 2  # 1 flop, 2 turn, 3 river
        # board as it was on each earlier street: (bk, bs, bm, bmax, bcat, n)
        pref = {}
        if PER_STREET:
            for s_ in range(1, cur_st):
                pb = board[:s_ + 2]
                k_ = sum(RK[c] for c in pb)
                ss_ = sum(SK[c] for c in pb)
                m_ = 0
                mx_ = 0
                for c in pb:
                    m_ |= RB[c]
                    if c >> 2 > mx_:
                        mx_ = c >> 2
                pref[len(pb) - 2] = (k_, ss_, m_, mx_, VAL[k_] >> 20, len(pb))
        for (j, npc, acts, b, fa, ds) in descs:
            L = [1.0] * 5
            old_rows = {}
            for (ast, code, frac) in acts:
                if code >= 2:
                    bb_ = b
                    if BLUFF_DISC:
                        sf = 1.0 if ast <= 1 else (0.72 if ast == 2 else 0.7)
                        if frac >= 0.95:
                            sf *= 0.8
                        elif frac <= 0.4:
                            sf *= 1.15
                        if sf < 1.0:
                            sf = 1.0 - (1.0 - sf) * ds
                        bb_ = b * sf + (1 - sf) * b * b
                        if bb_ > 0.95:
                            bb_ = 0.95
                    if code == 2:
                        row = (bb_, 0.55 if bb_ < 0.55 else bb_, 0.3 + 0.5 * bb_, 0.75, 1.0)
                    else:
                        row = (0.6 * bb_, 0.35 if bb_ < 0.58 else 0.6 * bb_, 0.12 + 0.3 * bb_, 0.4, 1.0)
                elif code == 1:
                    row = (fa, 0.8, 0.7, 0.95, 0.8)
                else:
                    row = (1.0, 1.0, 1.0, 0.75, 0.6)
                if ast in pref:
                    r0 = old_rows.get(ast)
                    if r0 is None:
                        old_rows[ast] = list(row)
                    else:
                        for k in range(5):
                            r0[k] *= row[k]
                    continue
                for k in range(5):
                    L[k] *= row[k]
            LC = (fa * 0.8, 0.7, 0.55 + 0.3 * fa, 0.95, 1.0)
            LR = (0.05 + 0.3 * fa, 0.4, 0.2 + 0.3 * fa, 0.6, 1.0)
            olds = tuple((pref[a_], r_) for a_, r_ in old_rows.items())
            tabs.append((npc, L, LC, LR, olds))
        deadline = t0 + 0.00020
        hard = t0 + 0.00035
        nsamp = 0
        maxs = 700
        cmask = 3 if nopp == 1 else (1 if nopp == 2 else 0)
        combos = COMBOS
        rng = range(nopp)
        while nsamp < maxs:
            if nsamp & cmask == 0:
                tn = _PC()
                if tn > hard or (tn > deadline and nsamp >= 12):
                    break
            nsamp += 1
            used = known
            w = 1.0
            wc = 1.0
            wr = 1.0
            ohs = []
            lcs = []
            lrs = []
            for (npc, L, LC, LR, olds) in tabs:
                for _t in range(6):
                    cb = combos[int(_rnd() * npc)]
                    if not (cb[2] & used):
                        break
                else:
                    while True:
                        a1 = deck[int(_rnd() * nd)]
                        a2 = deck[int(_rnd() * nd)]
                        if a1 != a2 and not ((CM[a1] | CM[a2]) & used):
                            break
                    cb = (a1, a2, CM[a1] | CM[a2])
                used |= cb[2]
                ohs.append(cb)
                t, dr = tf(cb[0], cb[1], bk, bs, bm, bmax, bcat, nb)
                bu = (1 if dr else 0) if t == 0 else t + 1
                w *= L[bu]
                for (pp, prow) in olds:
                    t2, dr2 = tf(cb[0], cb[1], pp[0], pp[1], pp[2], pp[3], pp[4], pp[5])
                    w *= prow[(1 if dr2 else 0) if t2 == 0 else t2 + 1]
                lc = LC[bu]
                lr = LR[bu]
                lcs.append(lc)
                lrs.append(lr)
                wc *= lc
                wr *= lr
            if w <= 0.0:
                continue
            if need:
                extra = _sample(deck, need + 2 * nopp)
                runout = [c for c in extra if not (CM[c] & used)][:need]
                fk = 0
                fs = 0
                for c in runout:
                    fk += RK[c]
                    fs += SK[c]
                full = bcards + tuple(runout)
            else:
                fk = fs = 0
                full = bcards
            mv = VAL[mk0 + fk]
            f = FS[ms0 + fs]
            if f >= 0:
                m = 0
                for c in full:
                    if c & 3 == f:
                        m |= RB[c]
                if h0 & 3 == f:
                    m |= RB[h0]
                if h1 & 3 == f:
                    m |= RB[h1]
                if FL[m] > mv:
                    mv = FL[m]
            res = 1.0
            ties = 0
            fb = bk + fk
            fsb = bs + fs
            for cb in ohs:
                a1 = cb[0]
                a2 = cb[1]
                ov = VAL[fb + RK[a1] + RK[a2]]
                f = FS[fsb + SK[a1] + SK[a2]]
                if f >= 0:
                    m = 0
                    for c in full:
                        if c & 3 == f:
                            m |= RB[c]
                    if a1 & 3 == f:
                        m |= RB[a1]
                    if a2 & 3 == f:
                        m |= RB[a2]
                    if FL[m] > ov:
                        ov = FL[m]
                if ov > mv:
                    res = 0.0
                    break
                if ov == mv:
                    ties += 1
            if res and ties:
                res = 1.0 / (1 + ties)
            W += w
            Ww += w * res
            x = w * wc
            Wc += x
            Wcw += x * res
            x = w * wr
            Wr += x
            Wrw += x * res
            for k in rng:
                cps[k] += w * lcs[k]
                crs[k] += w * lrs[k]
        if W <= 0:
            return 0.3, 0.3, 0.3, [0.5] * nopp, [0.5] * nopp, nsamp
        e = Ww / W
        ec = Wcw / Wc if Wc > 0 else e
        er = Wrw / Wr if Wr > 0 else e
        return e, ec, er, [x / W for x in cps], [x / W for x in crs], nsamp


try:  # keep import-time tables out of future GC scans (shorter GC pauses during play)
    import gc as _gc
    _gc.collect()
    _gc.freeze()
except Exception:
    pass
